const (
	shardCount   = 1000       // 哈希分片数量
	progressStep = 1000000    // 每100万行打印进度
)

func diffFilesWithProgress(fileA, fileB, fileC string) error {
	startTime := time.Now()
	tmpDir, err := os.MkdirTemp("", "filediff")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir)

	fmt.Printf("开始处理，创建临时分片目录: %s\n", tmpDir)

	// 阶段1: 处理文件B到分片
	if err := processFileToShards(fileB, tmpDir, "b"); err != nil {
		return err
	}
	fmt.Printf("文件B分片完成 [耗时: %v]\n", time.Since(startTime))

	// 阶段2: 处理文件A并输出差异
	if err := processFileA(fileA, fileC, tmpDir); err != nil {
		return err
	}

	totalTime := time.Since(startTime)
	fmt.Printf("\n处理完成! 总耗时: %v\n", totalTime)
	return nil
}

func processFileToShards(filePath, tmpDir, prefix string) error {
	shardFiles := make([]*os.File, shardCount)
	for i := range shardFiles {
		f, err := os.Create(filepath.Join(tmpDir, fmt.Sprintf("%s_shard_%d.tmp", prefix, i)))
		if err != nil {
			return err
		}
		defer f.Close()
		shardFiles[i] = f
	}

	file, err := os.Open(filePath)
	if err != nil {
		return err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)

	lineCount := 0
	for scanner.Scan() {
		line := scanner.Text()
		shardIdx := hash(line) % shardCount
		if _, err := shardFiles[shardIdx].WriteString(line + "\n"); err != nil {
			return err
		}

		lineCount++
		if lineCount%progressStep == 0 {
			fmt.Printf("已处理 %s: %d 万行\n", filePath, lineCount/10000)
		}
	}
	fmt.Printf("文件 %s 处理完成，共 %d 行\n", filePath, lineCount)
	return scanner.Err()
}

func processFileA(fileA, fileC, tmpDir string) error {
	aFile, err := os.Open(fileA)
	if err != nil {
		return err
	}
	defer aFile.Close()

	cFile, err := os.Create(fileC)
	if err != nil {
		return err
	}
	defer cFile.Close()

	writer := bufio.NewWriterSize(cFile, 8*1024*1024) // 8MB缓冲
	defer writer.Flush()

	scanner := bufio.NewScanner(aFile)
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)

	lineCount := 0
	shardCache := make(map[int]map[string]bool) // 分片缓存
	var mu sync.Mutex

	for scanner.Scan() {
		line := scanner.Text()
		shardIdx := int(hash(line) % shardCount)

		// 按需加载分片
		mu.Lock()
		if _, loaded := shardCache[shardIdx]; !loaded {
			if err := loadShard(tmpDir, shardIdx, shardCache); err != nil {
				mu.Unlock()
				return err
			}
		}
		exists := shardCache[shardIdx][line]
		mu.Unlock()

		if !exists {
			if _, err := writer.WriteString(line + "\n"); err != nil {
				return err
			}
		}

		lineCount++
		if lineCount%progressStep == 0 {
			fmt.Printf("处理文件A: 已比较 %d 万行 [差异行: %d]\n", lineCount/10000, lineCount-len(shardCache)*50000)
		}
	}

	fmt.Printf("文件A处理完成，共 %d 行\n", lineCount)
	return scanner.Err()
}

func loadShard(tmpDir string, shardIdx int, cache map[int]map[string]bool) error {
	file, err := os.Open(filepath.Join(tmpDir, fmt.Sprintf("b_shard_%d.tmp", shardIdx)))
	if err != nil {
		return err
	}
	defer file.Close()

	cache[shardIdx] = make(map[string]bool)
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		cache[shardIdx][scanner.Text()] = true
	}
	return scanner.Err()
}

func hash(s string) uint32 {
	h := fnv.New32a()
	h.Write([]byte(s))
	return h.Sum32()
}





